import {validateDraft} from './validation.js';
import {exercises,exerciseById,groups,equipmentLabels,searchExercises} from './data.js';
import {workSets,performance,e1rm,progression,within,hasObservation,lastSets,resistanceMetricsEligible} from './science.js';
import {esc,icon,btn,empty,field,select,num,dateLabel,modal,toast,chart} from './ui.js';
import {TODAY,uid} from './store.js';
import {programById,nextTarget,loadable} from './programs.js';
import {openFocus,focusOpen} from './focus.js';
import {lastTime,change,offerSteps} from './steps.js';
import {todayProgram,programPrompt} from './program-view.js';
import {suggestionCard} from './workouts.js';
import {figure,muscleLoad,groupChips} from './figure.js';
export const newSet=(reps=0,load=null)=>({id:uid(),reps,load,duration:0,distance:0,resistance:'',rpe:null,rir:null,warmup:false,done:false});
export const itemFor=(id,sets=3,reps=10,duration=30,previous=null)=>{const timed=exerciseById(id).tracking!=='reps-load',prior=i=>previous?.sets?.length?(previous.sets[i]??previous.sets.at(-1)).load??null:null;return {id:uid(),exerciseId:id,sets:Array.from({length:sets},(_,i)=>newSet(timed?0:reps,prior(i))),targetReps:timed?0:reps,targetDuration:timed?(duration||30):null,superset:'',notes:''}};
// A weighted exercise ticked Done with no weight: asked about once per set, then allowed (some machines have no number).
export const needsWeight=(e,set)=>e?.tracking==='reps-load'&&loadable(e)&&!(set.load>0);
export const noWeightOk=new Set();
// Sets whose numbers were typed or changed but never ticked Done. Only ticked sets are saved, so these are asked about on finish.
export const untickedEdited=d=>d.exercises.reduce((n,e)=>n+e.sets.filter(s=>s.edited&&!s.done).length,0);
export const withHistory=(C,id,sets,reps,duration)=>itemFor(id,sets,reps,duration,lastSets(C.state.sessions,id));
// A saved routine has one rep target per exercise. Treat it as a range of one rep and progress it like a program:
// same load until every set reaches the target, then the smallest sensible jump (double progression, plotkin2022).
// The change is only offered (steps.js); the workout starts at last time's numbers.
function progressed(C,e){const item=withHistory(C,e.exerciseId,e.sets,e.reps,e.duration),ex=exerciseById(e.exerciseId);if(ex.tracking!=='reps-load'||!(e.reps>0))return item;const t=nextTarget({exerciseId:e.exerciseId,sets:e.sets,reps:[e.reps,e.reps],rir:2},C.state.sessions,{units:C.state.profile.units});if(t.reason==='first')return item;const prev=lastTime(C.state.sessions,e.exerciseId),c=prev&&change({load:prev.load,reps:e.reps},{load:loadable(ex)?t.load:null,reps:Math.max(e.reps,t.reps)});if(c)item.suggest={load:c.load,reps:c.reps,from:c.from,note:t.note.slice(0,300)};return item}
export async function startWorkout(C,routineId){if(C.state.draft){location.hash='training';toast('Your unfinished workout is ready');return}const routine=C.state.routines.find(r=>r.id===routineId);C.state.draft={id:uid(),name:routine?.name||'New workout',date:TODAY(),startedAt:Date.now(),exercises:(routine?.exercises||[]).map(e=>progressed(C,e)),notes:'',restSeconds:routine?.restSeconds||120};await C.save('Workout started');location.hash='training';if(C.prefs.focusAuto&&C.state.draft.exercises.length)openFocus(C);offerSteps(C)}
const input=(value,attrs)=>`<input value="${esc(value??'')}" ${attrs}>`;
export function trainingView(C){const {state}=C,d=state.draft;return `<div class="page-head"><div><h1>${d?'Workout':'Training'}</h1></div><div class="button-group">${d?btn('Finish workout','finish-workout','primary','check'):btn('Start workout','start-workout','primary','plus')}${btn('Create routine','routine-new')}</div></div>${d?draftView(C,d):`${[todayProgram(C)||programPrompt(C),suggestionCard(C)].filter(Boolean).map(x=>`<div class="subsection-gap">${x}</div>`).join('')}<div class="grid equal"><section class="card"><div class="card-head"><h2>Routines</h2>${btn('New','routine-new','small','plus')}</div>${state.routines.length?state.routines.map(r=>`<div class="row"><div><strong>${esc(r.name)}</strong><p>${r.exercises.length} exercises · ${r.exercises.reduce((a,e)=>a+e.sets,0)} planned sets</p></div><div class="row-actions">${btn('Start','start-routine:'+r.id,'small primary')}${btn('Edit','routine-edit:'+r.id,'small')}</div></div>`).join(''):empty('No routines yet','Save a set of exercises to start workouts faster.','go-plan','Set up a routine')}</section><section class="card"><div class="card-head"><h2>History</h2><span class="badge">${state.sessions.length} sessions</span></div>${state.sessions.length?sessionRows(state.sessions):empty('No sessions yet','Finished workouts show up here.','start-workout','Start workout')}</section></div><section class="card subsection"><div class="card-head"><h2>Exercise performance</h2></div>${select('performance-ex','Choose an exercise',C.ui.performanceExercise||C.recentExercise(),exercises.filter(e=>e.category==='strength').map(e=>[e.id,e.name]))}<div id="performance-panel">${performancePanel(C,C.ui.performanceExercise||C.recentExercise())}</div></section>`}`}
// The muscle map for the workout in progress: planned working sets, with completed sets counted separately in the badge.
function workoutMap(d){if(!d.exercises.length)return '';const work=d.exercises.map(i=>({exerciseId:i.exerciseId,sets:i.sets.filter(s=>!s.warmup).length,done:i.sets.filter(s=>!s.warmup&&s.done).length})),load=muscleLoad(work),total=work.reduce((a,x)=>a+x.sets,0),done=work.reduce((a,x)=>a+x.done,0);return `<section class="card workout-map"><div class="card-head"><h2>Muscles in this workout</h2><span class="badge">${done} of ${total} sets done</span></div>${figure(load,{size:'small',caption:'Darker means more sets. A muscle that assists counts as half a set.'})}${groupChips(load)}</section>`}
function draftView(C,d){return `<div class="live-banner"><span><strong>Workout in progress</strong> · ${d.exercises.length} exercises${d.editingId?'':' · <span data-elapsed></span>'}</span><span class="meta"><span data-save-status>Saved</span></span></div><section class="card" style="margin-bottom:22px"><div class="form-grid">${field('session-name','Session name',d.name,'text','maxlength="100" data-draft-field="name" required')}${field('session-date','Date',d.date,'date','data-draft-field="date" required max="'+TODAY()+'"')}${field('restSeconds','Rest timer (seconds)',d.restSeconds,'number','min="0" max="1800" data-draft-field="restSeconds"')}${field('session-notes','Session notes',d.notes,'text','maxlength="1000" data-draft-field="notes"')}</div><div class="button-group">${btn('Focus mode','focus-open','primary')}${btn('Add exercise','pick-exercise','','plus')}${btn('Start rest timer','timer:'+d.restSeconds,'','time')}${btn('Equipment today','equipment-today')}${btn('Save as routine','draft-to-routine')}${btn('Discard workout','discard-workout','danger')}</div><div class="pref-row"><label class="check"><input type="checkbox" data-pref="autoRest" ${C.prefs.autoRest?'checked':''}>Start the rest timer when I complete a set</label><label class="check"><input type="checkbox" data-pref="restSound" ${C.prefs.restSound?'checked':''}>Beep when rest ends</label><label class="check"><input type="checkbox" data-pref="focusAuto" ${C.prefs.focusAuto?'checked':''}>Open focus mode when I start a workout</label></div><details class="fine"><summary>How loads are recorded</summary><p>Loads are recorded in ${C.loadUnit()}. Use the total external load you intend to compare; record per-hand, assisted, or machine conventions in exercise notes. No body mass is inferred. For unilateral movements, one set row represents a completed left/right pair; record side-specific observations in notes. RPE and RIR are subjective: RPE 10 ≈ 0 RIR, 9 ≈ 1 RIR, 8 ≈ 2 RIR.</p></details></section>${workoutMap(d)}${d.exercises.map(item=>exerciseEditor(C,item)).join('')}${d.exercises.length?'<div class="workout-footer"><span>Complete the sets you performed.</span>'+btn('Finish workout','finish-workout','primary','check')+'</div>':''}${!d.exercises.length?empty('No exercises yet','Add one to start logging sets.','pick-exercise','Add exercise'):''}`}
function exerciseEditor(C,item){const e=exerciseById(item.exerciseId),timed=e.tracking!=='reps-load',carry=e.pattern==='carry';const primary=timed?carry?['load','duration','distance']:e.tracking==='duration-distance'?['duration','distance']:['duration']:['load','reps'];const extra=['rir','rpe',...(!primary.includes('load')&&timed?['load']:[])];const labels={load:'Load ('+C.loadUnit()+')',reps:'Repetitions',duration:'Seconds',distance:'Metres',rpe:'RPE · 1–10',rir:'RIR · 0–10'};const fieldFor=(key,set,i)=>'<label class="set-field"><span>'+labels[key]+'</span>'+input(key==='load'&&Number.isFinite(set[key])?Number(C.displayLoad(set[key]).toFixed(2)):set[key],`type="number" inputmode="decimal" aria-label="${esc(e.name)} set ${i+1} ${key}" data-set-field="${key}" min="${key==='rpe'?1:0}" max="${key==='rpe'||key==='rir'?10:key==='reps'?1000:key==='load'?(C.state.profile.units==='imperial'?2204.62:1000):key==='duration'?86400:100000}" step="${['load','rpe'].includes(key)?'any':'1'}"`)+'</label>';const prev=lastSets(C.state.sessions.filter(s=>s.id!==C.state.draft.editingId),item.exerciseId),prog=timed?null:progression(C.state.sessions,item.exerciseId),fmt=s=>timed?[s.load>0?num(C.displayLoad(s.load),1)+' '+C.loadUnit():'',s.duration?num(s.duration)+' s':'',s.distance?num(s.distance)+' m':''].filter(Boolean).join(' · '):(Number.isFinite(s.load)?num(C.displayLoad(s.load),1)+' '+C.loadUnit()+' × ':'')+s.reps,history=(prev?`<p class="last-time"><strong>Last time</strong> · ${dateLabel(prev.date)} · ${prev.sets.map(fmt).join(', ')}</p>`:'')+(prog?.ready?`<p class="last-time ready"><strong>Ready to progress</strong> · you beat ${prog.target} reps with effort to spare in two sessions. Consider about ${num(C.displayLoad(prog.load),1)} ${C.loadUnit()}, rounded to your equipment. App heuristic; never applied automatically.</p>`:'');return `<section class="card session-exercise" data-exercise-editor="${item.id}"><div class="card-head"><div><div class="eyebrow">${esc(e.pattern.replaceAll('-',' '))}</div><h2>${esc(e.name)}</h2><p class="meta" style="margin:5px 0 0"><span data-set-count>${item.sets.filter(s=>s.done).length}/${item.sets.length} sets complete</span> · ${timed?'Target '+(item.targetDuration||30)+' seconds · record the performed duration or distance':'Target '+(item.range?(item.range[0]===item.range[1]?item.range[0]:item.range[0]+'–'+item.range[1]):item.targetReps)+' repetitions'+(item.targetLoad>0?' at '+num(C.displayLoad(item.targetLoad),1)+' '+C.loadUnit():'')+(Number.isInteger(item.targetRir)?' · leave about '+item.targetRir+' in reserve':'')}</p></div><div class="button-group">${btn('Details','exercise:'+e.id,'small')}${btn('Swap','swap-exercise:'+item.id,'small')}${btn('Remove','remove-draft-exercise:'+item.id,'small danger')}</div></div>${history}${item.why?`<p class="last-time">${esc(item.why)}</p>`:''}<div class="set-list">${item.sets.map((set,i)=>`<fieldset class="set-row ${set.done?'is-complete':''}" data-item="${item.id}" data-set="${set.id}"><legend>Set ${i+1}</legend><div class="set-main">${primary.map(key=>fieldFor(key,set,i)).join('')}<label class="set-done"><input type="checkbox" data-set-field="done" aria-label="Complete ${esc(e.name)} set ${i+1}" ${set.done?'checked':''}><span>Done</span></label></div><div class="set-options"><details><summary>Effort${set.rir!==null?' · '+set.rir+' RIR':''}</summary><div class="set-extra">${extra.map(key=>fieldFor(key,set,i)).join('')}<label class="check"><input type="checkbox" data-set-field="warmup" aria-label="${esc(e.name)} set ${i+1} warm-up" ${set.warmup?'checked':''}>Warm-up</label></div></details><button class="btn small ghost" data-action="remove-set:${item.id}|${set.id}" aria-label="Remove ${esc(e.name)} set ${i+1}">${icon('close')}</button></div><p class="set-error error" role="alert"></p></fieldset>`).join('')}</div><div class="button-group" style="margin:16px 0 20px">${btn('Add set','add-set:'+item.id,'small','plus')}${btn('Rest '+(item.rest||C.state.draft.restSeconds)+'s','timer:'+(item.rest||C.state.draft.restSeconds),'small','time')}</div><details class="exercise-notes"><summary>Notes${item.notes||item.superset?' · saved':''}</summary><div class="form-grid">${field('group-'+item.id,'Superset / circuit label',item.superset,'text',`maxlength="30" placeholder="e.g. A or Circuit 1" data-item-field="superset" data-item="${item.id}"`)}${field('notes-'+item.id,'Exercise notes / resistance',item.notes,'text',`maxlength="500" data-item-field="notes" data-item="${item.id}"`)}</div></details></section>`}
export function sessionRows(sessions){return [...sessions].sort((a,b)=>b.date.localeCompare(a.date)).map(s=>`<div class="row"><div><strong>${esc(s.name)}</strong><p>${dateLabel(s.date)} · ${s.exercises.reduce((a,e)=>a+workSets(e).length,0)} working sets · ${s.exercises.length} exercises</p></div>${btn('View','session:'+s.id,'small')}</div>`).join('')}
export function performancePanel(C,id){const e=exerciseById(id),h=performance(C.state.sessions,id),est=h.filter(p=>p.e1rm!==null),p=progression(C.state.sessions,id),volume=h.reduce((a,x)=>a+x.volume,0);return `<div class="metrics summary-metrics"><div><div class="meta">Best recorded load</div><div class="large-number">${h.some(p=>p.load!==null)?num(C.displayLoad(Math.max(...h.filter(p=>p.load!==null).map(p=>p.load))),1):'—'} <small>${C.loadUnit()}</small></div></div><div><div class="meta">Best estimated 1RM</div><div class="large-number">${est.length?num(C.displayLoad(Math.max(...est.map(p=>p.e1rm))),1):'—'} <small>${C.loadUnit()}</small></div></div><div><div class="meta">Sessions</div><div class="large-number">${h.length}</div></div></div>${h.length&&!est.length&&resistanceMetricsEligible(id)?'<p class="meta">The 1RM estimate needs a set where the reps plus any logged reps in reserve come to 12 or fewer.</p>':''}${chart(h.filter(p=>p.load!==null).map(p=>({date:p.date,value:C.displayLoad(p.load)})),{unit:'Best recorded load ('+C.loadUnit()+')'})}<div class="notice" style="margin-top:22px"><strong>Progression check${p.target?' · target '+p.target+' reps':''}</strong><p>${esc(p.message)}</p>${p.ready?`<p>Illustrative next load: ${num(C.displayLoad(p.load),1)} ${C.loadUnit()}. Round to available equipment.</p>`:''}<small>App heuristic; never applied automatically. ${C.sourceLinks(['acsm2026','acsm2009'])}</small></div><details class="fine"><summary>About this</summary><p>Epley estimates use completed, non-warm-up sets, adding any logged reps in reserve to the reps (unrated sets count as 0), up to 12 in total. Goals and programs use the same estimate. Estimates and load suggestions are suppressed for assistance, bands, bodyweight, machines, cables and timed movements. This is exercise-specific and imperfect; missing effort or higher-rep sets do not produce an estimate. ${C.sourceLinks(['lesuer1997','reynolds2006'])}</p></details>`}
export function picker(C,onChoose,filter=null){const d=modal('Choose an exercise',`<div class="field"><label for="exercise-search">Search movements</label><input id="exercise-search" type="search" placeholder="Name, muscle, equipment" autocomplete="off" enterkeyhint="search"></div><div id="pick-results"></div>`,()=>{});d.querySelector('.modal-footer').remove();const list=filter||exercises,muscles=e=>e.primary.map(g=>groups.find(x=>x.id===g)?.name).filter(Boolean).join(', ');const paint=q=>{d.querySelector('#pick-results').innerHTML=searchExercises(list,q).map(e=>`<div class="row"><div><strong>${esc(e.name)}</strong><p>${esc(muscles(e))}${e.primary.length?' · ':''}${e.equipment.map(x=>equipmentLabels[x]).join(' · ')}</p></div><button type="button" class="btn small" data-pick="${e.id}">Choose</button></div>`).join('')||`<div class="empty"><strong>No matching exercises</strong><p>Check the spelling, or try a muscle such as chest or a piece of equipment such as dumbbell.</p><button type="button" class="btn small" data-browse-all>Browse all exercises</button></div>`;const all=d.querySelector('[data-browse-all]');if(all)all.onclick=()=>{const box=d.querySelector('#exercise-search');box.value='';paint('');box.focus()};d.querySelectorAll('[data-pick]').forEach(b=>b.onclick=async()=>{await onChoose(b.dataset.pick);d.close()})};d.querySelector('#exercise-search').oninput=e=>paint(e.target.value);paint('')}
export function routineDialog(C,id='',fromDraft=false){const r=C.state.routines.find(r=>r.id===id)||{name:fromDraft?C.state.draft.name:'',restSeconds:120,exercises:fromDraft?C.state.draft.exercises.map(e=>({exerciseId:e.exerciseId,sets:e.sets.length,reps:e.targetReps||0,duration:e.targetDuration||30})):[]};const d=modal(id?'Edit routine':'Create routine',`${field('name','Routine name',r.name,'text','required maxlength="100"')}${field('rest','Rest between sets (seconds)',r.restSeconds,'number','required min="0" max="1800"')}<p class="meta">Choose movements and set targets. You can change every set during a workout.</p><div class="field"><label for="routine-search">Filter exercises</label><input id="routine-search" placeholder="Search movements"></div><div id="routine-list">${exercises.map(e=>{const v=r.exercises.find(x=>x.exerciseId===e.id);return `<div class="row" data-routine-name="${esc(e.name.toLowerCase())}"><label class="check" style="margin:0;flex:1"><input type="checkbox" name="exercise" value="${e.id}" ${v?'checked':''}>${esc(e.name)}</label><div style="display:flex;gap:8px;align-items:center"><small>${e.tracking==='reps-load'?'Sets / reps':'Sets / seconds'}</small><input name="sets-${e.id}" type="number" min="1" max="20" value="${v?.sets||3}" aria-label="${esc(e.name)} target sets" style="width:55px;padding:7px"><input name="reps-${e.id}" type="number" min="1" max="${e.tracking==='reps-load'?100:86400}" value="${e.tracking==='reps-load'?(v?.reps||10):(v?.duration||30)}" aria-label="${esc(e.name)} target ${e.tracking==='reps-load'?'reps':'seconds'}" style="width:55px;padding:7px"></div></div>`}).join('')}</div>`,async fd=>{const ids=fd.getAll('exercise');if(!ids.length)throw Error('Choose at least one exercise.');const updated={id:id||uid(),name:fd.get('name').trim(),restSeconds:Number(fd.get('rest')),exercises:ids.map(exerciseId=>({exerciseId,sets:Number(fd.get('sets-'+exerciseId)),reps:exerciseById(exerciseId).tracking==='reps-load'?Number(fd.get('reps-'+exerciseId)):0,duration:exerciseById(exerciseId).tracking==='reps-load'?null:Number(fd.get('reps-'+exerciseId))}))};if(!updated.name)throw Error('Enter a routine name.');if(id)C.state.routines=C.state.routines.map(x=>x.id===id?updated:x);else C.state.routines.push(updated);await C.save('Routine saved')});d.querySelector('#routine-search').oninput=e=>d.querySelectorAll('[data-routine-name]').forEach(r=>r.hidden=!r.dataset.routineName.includes(e.target.value.toLowerCase()));if(id){const b=document.createElement('button');b.type='button';b.className='btn danger';b.textContent='Delete routine';b.onclick=()=>C.confirm('Delete this routine?','Scheduled entries using it will be removed. Workout history stays available.',async()=>{C.state.routines=C.state.routines.filter(x=>x.id!==id);C.state.schedule=C.state.schedule.filter(x=>x.routineId!==id);await C.save('Routine deleted')});d.querySelector('.modal-footer').prepend(b)}}
export function sessionDialog(C,id){const s=C.state.sessions.find(x=>x.id===id);if(!s)return;const load=muscleLoad(s.exercises.map(i=>({exerciseId:i.exerciseId,sets:workSets(i).length}))),d=modal(s.name,`<p class="meta">${dateLabel(s.date)}${s.durationMinutes?' · '+num(s.durationMinutes)+' min':''}</p>${Object.keys(load).length?figure(load,{size:'small'})+groupChips(load):''}${s.exercises.map(item=>{const e=exerciseById(item.exerciseId);return `<h3>${esc(e?.name||item.exerciseId)}</h3>${item.superset?`<p class="meta">Group: ${esc(item.superset)}</p>`:''}<div class="table-wrap"><table class="data-table"><thead><tr><th>Set</th><th>Load</th><th>Reps</th><th>Time / distance</th><th>RIR</th><th>Type</th></tr></thead><tbody>${item.sets.filter(x=>x.done).map((x,i)=>`<tr><td>${i+1}</td><td>${num(C.displayLoad(x.load),1)} ${C.loadUnit()}</td><td>${num(x.reps)}</td><td>${x.duration?num(x.duration)+'s ':''}${x.distance?num(x.distance)+'m':''}</td><td>${x.rir??'—'}</td><td>${x.warmup?'Warm-up':'Working'}</td></tr>`).join('')}</tbody></table></div>${item.notes?`<p class="note-box">${esc(item.notes)}</p>`:''}`}).join('')}${s.notes?`<p class="notice">${esc(s.notes)}</p>`:''}<div class="button-group">${btn('Duplicate','duplicate-session:'+id)}${btn('Edit session','edit-session:'+id)}${btn('Delete','delete-session:'+id,'danger')}</div>`,()=>{});d.querySelector('.modal-footer').remove()}
export async function trainingAction(a,id,C){const d=C.state.draft;if(a==='start-workout'){await startWorkout(C);return true}if(a==='start-routine'){await startWorkout(C,id);return true}if(a==='routine-new'){routineDialog(C);return true}if(a==='routine-edit'){routineDialog(C,id);return true}if(a==='draft-to-routine'){routineDialog(C,'',true);return true}if(a==='pick-exercise'){picker(C,async id=>{d.exercises.push(withHistory(C,id));await C.save('Exercise added');if(C.prefs.focusAuto&&d.exercises.length===1&&!focusOpen())openFocus(C)});return true}if(a==='add-set'){const item=d.exercises.find(e=>e.id===id),last=item.sets.at(-1);item.sets.push({...newSet(last?.reps||0,last?.load??null),duration:last?.duration??0,distance:last?.distance??0,rir:null});await C.save('Set added');return true}if(a==='remove-set'){const [itemId,setId]=id.split('|');d.exercises.find(e=>e.id===itemId).sets=d.exercises.find(e=>e.id===itemId).sets.filter(s=>s.id!==setId);await C.save('Set removed');return true}if(a==='remove-draft-exercise'){C.confirm('Remove this exercise?','Its sets will be removed from this unfinished workout.',async()=>{d.exercises=d.exercises.filter(e=>e.id!==id);await C.save('Exercise removed')});return true}if(a==='discard-workout'){C.confirm('Discard this workout?','The unfinished sets will be deleted.',async()=>{C.state.draft=null;await C.save('Workout discarded')});return true}if(a==='finish-workout'){if(!d.exercises.some(e=>workSets(e).length||e.sets.some(s=>s.done&&s.warmup)))throw Error('Tick Done on the sets you did before finishing. Only ticked sets are saved.');const left=untickedEdited(d);if(left&&id!=='anyway'){const q=modal(left===1?'1 set isn’t ticked Done':left+' sets aren’t ticked Done',`<p>${left===1?'One set has':left+' sets have'} numbers but ${left===1?'isn’t':'aren’t'} ticked Done. Only ticked sets are saved, so ${left===1?'it':'they'} will be left out of your history.</p>`,async()=>{await trainingAction('finish-workout','anyway',C)});q.querySelector('.modal-footer [data-close]').textContent='Go back';q.querySelector('.modal-footer [type=submit]').textContent='Save anyway';return true}if(!d.name.trim())throw Error('Enter a session name.');if(d.date>TODAY())throw Error('Choose today or an earlier date.');C.validateDraft(d);if(document.querySelector('[data-draft-field]:invalid,[data-item-field]:invalid,[data-set-field]:invalid'))throw Error('Check the highlighted workout fields before finishing.');validateDraft(d,{requireTracking:true});const session=completedSession(d);if(d.editingId){session.id=d.editingId;C.state.sessions=C.state.sessions.map(s=>s.id===d.editingId?session:s)}else{C.state.sessions.push(session);const p=C.state.program;if(p&&session.program?.templateId===p.templateId){p.completed++;p.next=(session.program.day+1)%programById(p.templateId).days.length}}C.state.draft=null;C.ui.equipmentToday=null;C.stopRest();await C.save('Workout saved');return true}if(a==='session'){sessionDialog(C,id);return true}if(a==='duplicate-session'||a==='edit-session'){if(d)throw Error('Finish or discard your current workout first.');const s=structuredClone(C.state.sessions.find(s=>s.id===id));if(a==='duplicate-session'){s.startedAt=Date.now();s.id=uid();s.date=TODAY();s.name+=' · repeat';delete s.program;s.exercises.forEach(e=>e.sets.forEach(x=>x.done=false))}else s.editingId=id;C.state.draft=s;document.querySelector('#modal').close();location.hash='training';await C.save(a==='edit-session'?'Session ready to edit':'Workout duplicated');return true}if(a==='delete-session'){C.confirm('Delete this session?','This removes it from your history and muscle analytics.',async()=>{C.state.sessions=C.state.sessions.filter(s=>s.id!==id);await C.save('Session deleted')});return true}return false}
export async function trainingInput(e,C){
 const el=e.target;if(el.name==='performance-ex'){C.ui.performanceExercise=el.value;document.querySelector('#performance-panel').innerHTML=performancePanel(C,el.value);return true}
 if(!el.matches('[data-draft-field],[data-item-field],[data-set-field]'))return false;
 const status=document.querySelector('[data-save-status]'),row=el.closest('[data-set]'),error=row?.querySelector('.set-error');
 if(!el.checkValidity()){el.setAttribute('aria-invalid','true');if(error)error.textContent=el.validationMessage;if(status)status.textContent='Check this field · edit not saved';return true}
 el.removeAttribute('aria-invalid');if(error)error.textContent='';const draft=structuredClone(C.state.draft);
 if(el.dataset.draftField){const key=el.dataset.draftField;draft[key]=key==='restSeconds'?Number(el.value):el.value}
 if(el.dataset.itemField)draft.exercises.find(x=>x.id===el.dataset.item)[el.dataset.itemField]=el.value;
 if(el.dataset.setField){const item=draft.exercises.find(x=>x.id===row.dataset.item),set=item.sets.find(x=>x.id===row.dataset.set),key=el.dataset.setField;set[key]=el.type==='checkbox'?el.checked:el.value===''?null:key==='load'?C.parseLoad(Number(el.value)):Number(el.value);if(['load','reps','duration','distance'].includes(key))set.edited=true;if(key==='done'&&set.done){try{validateDraft({...draft,exercises:[{...item,sets:[set]}]},{requireTracking:true})}catch(err){el.checked=false;if(error)error.textContent=err.message;return true}if(needsWeight(exerciseById(item.exerciseId),set)&&!noWeightOk.has(set.id)){noWeightOk.add(set.id);el.checked=false;if(error)error.textContent='No weight entered. Add the weight you used, or tick Done again to save without it.';row.querySelector('[data-set-field="load"]')?.focus();return true}}if(set.done&&!hasObservation(set,item.exerciseId)){set.done=false;row.querySelector('[data-set-field="done"]').checked=false}if(key==='done'&&set.done)C.startRest(item.rest||draft.restSeconds);row.classList.toggle('is-complete',set.done);row.closest('[data-exercise-editor]').querySelector('[data-set-count]').textContent=item.sets.filter(s=>s.done).length+'/'+item.sets.length+' sets complete'}
 try{validateDraft(draft,{editing:true});if(JSON.stringify(draft)===JSON.stringify(C.state.draft))return true;C.state.draft=draft;if(status)status.textContent='Saving…';await C.persist();if(status)status.textContent='Saved'}catch(err){if(error)error.textContent=err.message;if(status)status.textContent='Not saved · check this field';throw err}return true;
}

export function completedSession(d,now=Date.now()){validateDraft(d,{requireTracking:true});const session=structuredClone(d);session.exercises=session.exercises.filter(e=>e.sets.some(s=>s.done)).map(({suggest,...e})=>({...e,sets:e.sets.filter(s=>s.done).map(({edited,...s})=>s)}));session.durationMinutes=d.editingId?d.durationMinutes:Math.max(1,Math.round((now-d.startedAt)/60000));delete session.editingId;return session}
